// function getNestedValue(obj, path) mein object aur path array do
// Agar obj nahi: undefined
// Path pehle-pehle traverse karo
// Agar kahi undefined mila: undefined
// Warna final value return karo

solution:
function getNestedValue(obj, path) {
  if (!obj || !Array.isArray(path)) return undefined
  let current = obj
  for (const key of path) {
    if (current === null || current === undefined) return undefined
    current = current[key]
  }
  return current
}
